import { useEffect, useId, useRef, useState, type InputHTMLAttributes } from "react";
import { Search, X } from "lucide-react";
import { cn } from "@/lib/cn";

// KMP-C22 (specs/KMP-C22-search-field.md). Native input type=search.
// The field has no live region and never calls `announce`: the consumer (Search screen) announces
// the result count after it filters (G-S1). The field only emits value changes and clear events.
// Escape clears by browser default for type=search; there is deliberately no Escape handler.

export type SearchFieldProps = {
  /** Visually hidden label; it is the accessible name (Q-S1, provisional). */
  label?: string;
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  /** Raw text as typed, never trimmed. Not called while an input-method composition is active; called once when it ends. */
  onValueChange?: (value: string) => void;
  /** The clear button was pressed (onValueChange("") is also called). */
  onClear?: () => void;
  /** Accessible name of the clear button (decided: "Clear search"). */
  clearLabel?: string;
  lang?: string;
  className?: string;
} & Pick<InputHTMLAttributes<HTMLInputElement>, "name" | "id" | "aria-describedby">;

export function SearchField({
  label = "Search dishes and ingredients",
  placeholder = "Search dishes and ingredients",
  value,
  defaultValue = "",
  onValueChange,
  onClear,
  clearLabel = "Clear search",
  lang,
  className,
  id: idProp,
  name,
  "aria-describedby": describedBy,
}: SearchFieldProps) {
  const auto = useId();
  const id = idProp ?? auto;
  const [text, setText] = useState(value ?? defaultValue);
  const composing = useRef(false);
  // Safari fires compositionend before the last input event: remember what was emitted so one composition gives one call.
  const lastEmitted = useRef(value ?? defaultValue);
  const emit = (v: string) => {
    if (v === lastEmitted.current) return;
    lastEmitted.current = v;
    onValueChange?.(v);
  };
  const input = useRef<HTMLInputElement>(null);

  // Follow an externally controlled value, but never fight an active composition.
  useEffect(() => {
    if (value !== undefined && !composing.current) {
      setText(value);
      lastEmitted.current = value;
    }
  }, [value]);

  return (
    <div className={cn("flex flex-col", className)}>
      <label htmlFor={id} className="sr-only">
        {label}
      </label>
      <div
        className={cn(
          "flex min-h-control items-center gap-gap-sm rounded-control border-bw-default border-border-strong bg-surface-raised ps-inset-md pe-1",
          "has-[input:focus-visible]:outline has-[input:focus-visible]:outline-ring has-[input:focus-visible]:outline-offset-ring has-[input:focus-visible]:outline-focus-ring",
        )}
      >
        <Search aria-hidden="true" className="size-icon-md shrink-0 text-text-muted" />
        <input
          ref={input}
          id={id}
          type="search"
          lang={lang}
          value={text}
          placeholder={placeholder}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          enterKeyHint="search"
          onChange={(e) => {
            setText(e.target.value);
            if (!composing.current) emit(e.target.value);
          }}
          onCompositionStart={() => (composing.current = true)}
          onCompositionEnd={(e) => {
            composing.current = false;
            emit(e.currentTarget.value);
          }}
          className={cn(
            "min-w-0 flex-1 bg-transparent py-1 font-body text-ui-body font-regular leading-normal text-text [outline-style:none]",
            "placeholder:text-text-subtle placeholder:opacity-100",
            // the browser's own clear control is suppressed so there is never a double control
            "[&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden",
          )}
          name={name}
          aria-describedby={describedBy}
        />
        {text !== "" && (
          <button
            type="button"
            aria-label={clearLabel}
            onClick={() => {
              setText("");
              emit("");
              onClear?.();
              input.current?.focus();
            }}
            className={cn(
              "inline-flex size-icon-target shrink-0 items-center justify-center rounded-pill text-text transition-colors duration-fast ease-standard",
              "hover:bg-surface-sunken active:bg-surface-sunken",
              "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring",
            )}
          >
            <X aria-hidden="true" className="size-icon-lg" />
          </button>
        )}
      </div>
    </div>
  );
}
